#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        // to_camel logic
        int i = 0;
        int len = strlen(argv[2]);
        char *out = malloc(len + 1);
        int j = 0;
        for (i = 0; i < len; i++) {
            if (argv[2][i] == '_') {
                i++;
                out[j] = toupper(argv[2][i]);
                j++;
            } else {
                out[j] = argv[2][i];
                j++;
            }
        }
        out[j] = '\0';
        printf("%s\n", out);
        free(out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        // to_snake logic
        int i = 0;
        int len = strlen(argv[2]);
        char *out = malloc(len * 2 + 1);
        int j = 0;
        for (i = 0; i < len; i++) {
            if (isupper(argv[2][i])) {
                out[j] = '_';
                j++;
                out[j] = tolower(argv[2][i]);
                j++;
            } else {
                out[j] = argv[2][i];
                j++;
            }
        }
        out[j] = '\0';
        printf("%s\n", out);
        free(out);
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
